
CREATE TABLE `FastSqlOrder` (`Id` INT AUTO_INCREMENT NOT NULL, `CustomerName` VARCHAR(64) NULL, `CustomerId` INT NOT NULL, `Amount` DECIMAL(18,4) NOT NULL, `State` INT NOT NULL, `CreatedAt` DATETIME(3) NOT NULL, `PaidAt` DATETIME(3) NULL, `Note` TEXT NULL, CONSTRAINT `PK_FastSqlOrder` PRIMARY KEY (`Id`)) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 ; CREATE INDEX `IX_FastSqlOrder_CreatedAt` ON `FastSqlOrder` ( `CreatedAt` ASC )
